public static int findNthLeapYear(int Y, int N) throws IllegalArgumentException {
    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Both Y and N must be positive integers.");
    }

    int count = 0;
    int year = Y;

    while (count < N) {
        if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
            count++;
        }
        if (count < N) {
            year++;
        }
    }

    return year;
}

