        throw new IllegalArgumentException("Inputs must be positive integers.");
    }

    int count = 0;
    for (int year = Y; year < Integer.MAX_VALUE; year++) {
        if (isLeapYear(year)) {
            count++;
            if (count == N) {
                return year;
            }
        }
    }

    throw new RuntimeException("Unable to find the Nth leap year within the range of integers.");
