import java.util.Arrays;
import java.util.List;

public int findLargestSubstring(List<String> strings) {
    int maxSubstringSize = 0;

    // Check each string in the list
    for (String str : strings) {
        int n = str.length();
        // Check the substring from each starting point and length
        for (int i = 0; i < n; i++) {
            for (int len = 1; i + len <= n; len++) {
                String substring = str.substring(i, i + len);
                String reversed = new StringBuilder(substring).reverse().toString();
                // Check if the substring or its reverse is in any other string
                boolean isValid = strings.stream().anyMatch(s -> s.contains(substring) || s.contains(reversed));
                if (isValid) {
                    maxSubstringSize = Math.max(maxSubstringSize, len);
                }
            }
        }
    }

    return maxSubstringSize;
}
