public static int countOilDeposits(char[][] grid) {
    int count = 0;
    int rows = grid.length;
    if (rows == 0) return count;
    int cols = grid[0].length;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@') {
                count++;
                dfs(grid, i, j);
            }
        }
    }

    return count;
}

private static void dfs(char[][] grid, int i, int j) {
    int rows = grid.length;
    int cols = grid[0].length;

    if (i < 0 || i >= rows || j < 0 || j >= cols || grid[i][j] != '@') {
        return;
    }

    grid[i][j] = '*'; // Mark as visited

    // Explore all 8 directions
    dfs(grid, i - 1, j); // up
    dfs(grid, i + 1, j); // down
    dfs(grid, i, j - 1); // left
    dfs(grid, i, j + 1); // right
    dfs(grid, i - 1, j - 1); // up-left
    dfs(grid, i - 1, j + 1); // up-right
    dfs(grid, i + 1, j - 1); // down-left
    dfs(grid, i + 1, j + 1); // down-right
}
