public static int countDoubles(int[] numbers) {
    if (numbers == null) {
        throw new IllegalArgumentException("Input array must not be null");
    }

    Set<Integer> seenNumbers = new HashSet<>();
    Set<Integer> doubleNumbers = new HashSet<>();

    for (int number : numbers) {
        if (seenNumbers.contains(number * 2) || (number % 2 == 0 && seenNumbers.contains(number / 2))) {
            doubleNumbers.add(number);
        }
        seenNumbers.add(number);
    }

    return doubleNumbers.size();
}
