public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || start.length != 2 || end.length != 2 || paths == null || paths.length == 0) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    return canTravel(start[0], start[1], end[0], end[1], paths, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravel(int startX, int startY, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (startX == endX && startY == endY) {
        return true;
    }

    visited[startX][startY] = true;

    for (int[] path : paths) {
        int fromX = path[0];
        int fromY = path[1];
        int toX = path[2];
        int toY = path[3];

