public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || paths == null) {
        throw new IllegalArgumentException("Inputs cannot be null");
    }
    if (start.length != 2 || end.length != 2) {
        throw new IllegalArgumentException("Start and end coordinates must have exactly 2 elements");
    }
    if (paths.length == 0) {
        if (start[0] == end[0] && start[1] == end[1]) {
            return "can be travelled";
        } else {
            return "cannot be travelled";
        }
    }
    boolean[][] grid = new boolean[n][n];
    for (int i = 0; i < paths.length; i++) {
        int x1 = paths[i][0];
        int y1 = paths[i][1];
        int x2 = paths[i][2];
        int y2 = paths[i][3];
        if (x1 == x2) {
            if (y1 > y2) {
                for (int j = y2; j <= y1; j++) {
                    grid[x1][j] = true;
                }
            } else {
                for (int j = y1; j <= y2; j++) {
                    grid[x1][j] = true;
                }
            }
        } else if (y1 == y2) {
            if (x1 > x2) {
                for (int j = x2; j <= x1; j++) {
                    grid[j][y1] = true;
                }
            } else {
                for (int j = x1; j <= x2; j++) {
                    grid[j][y1] = true;
                }
            }
        }
    }
    boolean[][] visited = new boolean[n][n];
    return canTraverse(grid, start[0], start[1], end[0], end[1], visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTraverse(boolean[][] grid, int x, int y, int endX, int endY, boolean[][] visited) {
    if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length || grid[x][y] || visited[x][y]) {
        return false;
    }
    if (x == endX && y == endY) {
        return true;
    }
    visited[x][y] = true;
    boolean top = canTraverse(grid, x - 1, y, endX, endY, visited);
    boolean bottom = canTraverse(grid, x + 1, y, endX, endY, visited);
    boolean left = canTraverse(grid, x, y - 1, endX, endY, visited);
    boolean right = canTraverse(grid, x, y + 1, endX, endY, visited);
    visited[x][y] = false;
    return top || bottom || left || right;
}
