public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    int startX = start[0];
    int startY = start[1];
    int endX = end[0];
    int endY = end[1];

    if (startX < 0 || startX >= n || startY < 0 || startY >= n || endX < 0 || endX >= n || endY < 0 || endY >= n) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    Queue<int[]> queue = new LinkedList<>();
    queue.add(new int[]{startX, startY});
    visited[startX][startY] = true;

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int x = current[0];
        int y = current[1];

        if (x == endX && y == endY) {
            return "can be travelled";
        }

        int[] direction = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        for (int[] d : direction) {
            int newX = x + d[0];
            int newY = y + d[1];

            if (newX >= 0 && newX < n && newY >= 0 && newY < n && !visited[newX][newY]) {
                for (int[] path : paths) {
                    if ((path[0] == x && path[1] == y && path[2] == newX && path[3] == newY) ||
                        (path[0] == newX && path[1] == newY && path[2] == x && path[3] == y)) {
                        queue.add(new int[]{newX, newY});
                        visited[newX][newY] = true;
                        break;
                    }
                }
            }
        }
    }

    return "cannot be travelled";
}
