import java.util.HashSet;
import java.util.Set;

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start.length != 2 || end.length != 2) {
        throw new IllegalArgumentException("Start and end coordinates must be of length 2");
    }

    Set<String> visited = new HashSet<>();
    Set<String> pathSet = new HashSet<>();
    for (int[] path : paths) {
        if (path.length != 2) {
            throw new IllegalArgumentException("Each path must be of length 2");
        }
        pathSet.add(path[0] + "," + path[1]);
    }

    if (!pathSet.contains(start[0] + "," + start[1]) || !pathSet.contains(end[0] + "," + end[1])) {
        return "cannot be travelled";
    }

    return canTravelMazeRecursive(start[0], start[1], end[0], end[1], pathSet, visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean canTravelMazeRecursive(int x, int y, int endX, int endY, Set<String> pathSet, Set<String> visited) {
    String current = x + "," + y;
    if (x == endX && y == endY) {
        return true;
    }
    if (visited.contains(current)) {
        return false;
    }
    visited.add(current);

    int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
    for (int[] direction : directions) {
        int newX = x + direction[0];
        int newY = y + direction[1];
        String next = newX + "," + newY;
        if (pathSet.contains(next) && canTravelMazeRecursive(newX, newY, endX, endY, pathSet, visited)) {
            return true;
        }
    }

    visited.remove(current);
    return false;
}
