import java.util.HashSet;
import java.util.Set;

public class ApproximateValue {
    public static String appx(String word1, String word2) {
        if (word1 == null || word2 == null) {
            throw new IllegalArgumentException("Input strings cannot be null");
        }

        Set<Character> set1 = new HashSet<>();
        for (char c : word1.toCharArray()) {
            set1.add(c);
        }

        Set<Character> set2 = new HashSet<>();
        for (char c : word2.toCharArray()) {
            set2.add(c);
        }

        int commonCount = 0;
        for (char c : set1) {
            if (set2.contains(c)) {
                commonCount++;
            }
        }

        int lengthSum = word1.length() + word2.length();

        if (lengthSum == 0) {
            return "appx("", "") = 0";
        }

        int gcd = gcd(commonCount, lengthSum);
        return String.format("appx(%s, %s) = %d/%d", word1, word2, commonCount / gcd, lengthSum / gcd);
    }

    private static int gcd(int a, int b) {
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }

    public static void main(String[] args) {
        System.out.println(appx("CAR", "CART")); // "appx(CAR, CART) = 6/7"
        System.out.println(appx("TURKEY", "CHICKEN")); // "appx(TURKEY, CHICKEN) = 4/13"
        System.out.println(appx("MONEY", "POVERTY")); // "appx(MONEY, POVERTY) = 1/3"
        System.out.println(appx("ROUGH", "PESKY")); // "appx(ROUGH, PESKY) = 0"
        System.out.println(appx("A", "A")); // "appx(A, A) = 1"
    }
}
