    boolean[] visited = new boolean[word2.length()];

    for (int i = 0; i < word1.length(); i++) {
        char ch = word1.charAt(i);
        for (int j = 0; j < word2.length(); j++) {
            if (!visited[j] && word2.charAt(j) == ch) {
                commonCount++;
                visited[j] = true;
                break;
            }
        }
    }

    int sumOfLengths = word1.length() + word2.length();

    if (sumOfLengths == 0) {
        throw new IllegalArgumentException("Sum of lengths must not be zero");
    }

    int gcd = gcd(commonCount, sumOfLengths);
    int numerator = commonCount / gcd;
    int denominator = sumOfLengths / gcd;

    return "appx(" + word1.toUpperCase() + ", " + word2.toUpperCase() + ") = " + numerator + "/" + denominator;
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
