        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }

    return dfs(graph, hasApple, 0, -1) * 2;
}

private int dfs(List<List<Integer>> graph, boolean[] hasApple, int node, int parent) {
    int totalTime = 0;

    for (int neighbor : graph.get(node)) {
        if (neighbor == parent) {
            continue;
        }
        int time = dfs(graph, hasApple, neighbor, node);
        if (time > 0 || hasApple[neighbor]) {
            totalTime += time;
        }
    }

    return totalTime + (hasApple[node] ? 1 : 0);
}
