public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) {
        return false;
    }
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    for (int i = 0; i < (1 << n); i++) {
        int subsetSum = 0;
        int subsetSize = 0;
        for (int j = 0; j < n; j++) {
            if ((i & (1 << j)) != 0) {
                subsetSum += nums[j];
                subsetSize++;
            }
        }
        if (subsetSize > 0 && subsetSize < n && 100 * subsetSum * (n - subsetSize) == 100 * sum * subsetSize) {
            return true;
        }
    }
    return false;
}
