public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;

    double sum = 0;
    for (int num : nums) {
        sum += num;
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0) {
            if (findSubset(nums, i, sum * i / n)) {
                return true;
            }
        }
    }

    return false;
}

private boolean findSubset(int[] nums, int k, int target) {
    boolean[][] dp = new boolean[nums.length + 1][target + 1];

    for (int i = 0; i <= nums.length; i++) {
        dp[i][0] = true;
    }

    for (int i = 1; i <= nums.length; i++) {
        for (int j = 1; j <= target; j++) {
            if (nums[i - 1] <= j) {
                dp[i][j] = dp[i - 1][j] || dp[i - 1][j - nums[i - 1]];
            } else {
                dp[i][j] = dp[i - 1][j];
            }
        }
    }

    return dp[nums.length][target];
}
