public boolean hasAllCodes(String s, int k) {
    if (s.length() < Math.pow(2, k)) {
        return false;
    }
    HashSet<String> uniqueSubstrings = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
