public int minInsertions(String s) {
    int bal = 0; // Balance of the parentheses
    int ans = 0; // Number of insertions needed

    for (int i = 0; i < s.length(); ++i) {
        if (s.charAt(i) == '(') {
            ++bal; // Increment balance for an opening parenthesis
        } else {
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                ++i; // Skip the next character as it forms a pair
            } else {
                ++ans; // Insert a matching closing parenthesis
            }
            --bal; // Decrement balance for a closing parenthesis
            if (bal == -1) {
                ++ans; // Insert a matching opening parenthesis
                bal = 0; // Reset balance
            }
        }
    }

    return ans + 2 * bal; // Add remaining balanced parentheses to the answer
}
