public int findMinFibonacciNumbers(int k) {
    List<Integer> fibonacci = new ArrayList<>();
    fibonacci.add(1);
    fibonacci.add(1);

    // Generate Fibonacci numbers up to k
    while (fibonacci.get(fibonacci.size() - 1) < k) {
        int next = fibonacci.get(fibonacci.size() - 1) + fibonacci.get(fibonacci.size() - 2);
        fibonacci.add(next);
    }

    int count = 0;
    // Subtract the largest Fibonacci number less than or equal to k and increment count
    while (k > 0) {
        int lastIndex = fibonacci.size() - 1;
        if (fibonacci.get(lastIndex) <= k) {
            k -= fibonacci.get(lastIndex);
            count++;
        } else {
            fibonacci.remove(lastIndex);
        }
    }

    return count;
}
