public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
        k--;
    }
    int index = n - 1;
    while (k > 0) {
        int add = Math.min(25, k);
        result[index] += add;
        k -= add;
        index--;
    }
    return String.valueOf(result);
}
