public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low <= 9) {
        for (int i = low; i <= 9; i++) {
            result.add(i);
        }
    }
    Queue<Integer> queue = new LinkedList<>();
    for (int i = 10; i <= high; i++) {
        int lastDigit = i % 10;
        if (lastDigit != 0) {
            queue.offer(i - 1);
        }
        if (lastDigit != 9) {
            queue.offer(i + 1);
        }
    }
    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current > high) {
            break;
        }
        result.add(current);
        int lastDigit = current % 10;
        if (lastDigit != 0) {
            queue.offer(current * 10 + lastDigit - 1);
        }
        if (lastDigit != 9) {
            queue.offer(current * 10 + lastDigit + 1);
        }
    }
    Collections.sort(result);
    return result;
}
