            if (isPerfectSquare(sum1)) {
                graph.computeIfAbsent(i, k -> new ArrayList<>()).add(j);
                graph.computeIfAbsent(j, k -> new ArrayList<>()).add(i);
            }
            if (isPerfectSquare(sum2)) {
                graph.computeIfAbsent(i, k -> new ArrayList<>()).add(j);
                graph.computeIfAbsent(j, k -> new ArrayList<>()).add(i);
            }
        }
    }

    int[] count = new int[1];
    for (int i = 0; i < n; i++) {
        if (graph.containsKey(i)) {
            boolean[] visited = new boolean[n];
            visited[i] = true;
            dfs(graph, visited, count, 1, i);
        }
    }

    return count[0];
}

private static void dfs(Map<Integer, List<Integer>> graph, boolean[] visited, int[] count, int size, int current) {
    if (size == graph.size()) {
        count[0]++;
        return;
    }

    for (int neighbor : graph.get(current)) {
        if (!visited[neighbor]) {
            visited[neighbor] = true;
            dfs(graph, visited, count, size + 1, neighbor);
            visited[neighbor] = false;
        }
    }
}

private static boolean isPerfectSquare(int num) {
    if (num < 0) {
        return false;
    }
    int root = (int) Math.sqrt(num);
    return root * root == num;
}
