public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;

    int[][] dp = new int[n][1 << n];
    for (int[] row : dp) {
        Arrays.fill(row, -1);
    }

    return backtrack(A, 0, 0, dp);
}

private static boolean isPerfectSquare(int num) {
    int root = (int) Math.sqrt(num);
    return root * root == num;
}

private static int backtrack(int[] A, int index, int mask, int[][] dp) {
    int n = A.length;
    if (index == n - 1) {
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) == 0) {
                return isPerfectSquare(A[index] + A[i]) ? 1 : 0;
            }
        }
        return 0;
    }

    if (dp[index][mask] != -1) return dp[index][mask];

    int count = 0;
    for (int i = 0; i < n; i++) {
        if ((mask & (1 << i)) == 0) {
            if (isPerfectSquare(A[index] + A[i])) {
                count += backtrack(A, index + 1, mask | (1 << i), dp);
            }
        }
    }

    return dp[index][mask] = count;
}
