import java.util.ArrayList;
import java.util.List;

public class CenterSymmetricNumbers {

    public static List<String> centerSymmetricNumbers(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("Input must be a non-negative integer.");
        }
        List<String> result = new ArrayList<>();
        if (n == 0) return result;
        if (n == 1) {
            result.add("0");
            result.add("1");
            result.add("8");
            return result;
        }
        generateCenterSymmetricNumbers(n, 0, result, new char[n]);
        return result;
    }

    private static void generateCenterSymmetricNumbers(int n, int index, List<String> result, char[] current) {
        if (index > n / 2) {
            result.add(new String(current));
            return;
        }

        char[] choices = { '0', '1', '6', '8', '9' };
        for (int i = 0; i < choices.length; i++) {
            if (i == 0 && index == 0 && n > 1) continue; // Avoid leading zero for numbers longer than 1
            if (i == 2 || i == 4) {
                current[index] = choices[i];
                current[n - 1 - index] = getMirror(choices[i]);
                generateCenterSymmetricNumbers(n, index + 1, result, current);
            } else {
                current[index] = choices[i];
                current[n - 1 - index] = choices[i];
                generateCenterSymmetricNumbers(n, index + 1, result, current);
            }
        }
    }

    private static char getMirror(char c) {
        switch (c) {
            case '6': return '9';
            case '9': return '6';
            default: return c;
        }
    }

    public static void main(String[] args) {
        System.out.println(centerSymmetricNumbers(2)); // Output: [11,69,88,96]
        System.out.println(centerSymmetricNumbers(1)); // Output: [0,1,8]
    }
}
