public static List<String> centerSymmetricNumbers(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer.");
    }
    List<String> result = new ArrayList<>();
    if (n == 0) {
        return result;
    }
    if (n == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }
    int[] digits = {0, 1, 6, 8, 9};
    char[] half = new char[n / 2];
    generate(n, half, 0, result, digits);
    return result;
}

private static void generate(int n, char[] half, int index, List<String> result, int[] digits) {
    if (index == half.length) {
        StringBuilder full = new StringBuilder();
        for (int i = 0; i < half.length; i++) {
            full.append(half[i]);
        }
        if (n % 2 == 0) {
            result.add(full + new StringBuilder(full).reverse().toString());
        } else {
            for (char c : new char[]{'0', '1', '8'}) {
                result.add(full + c + new StringBuilder(full).reverse().toString());
            }
        }
        return;
    }
    for (int i = 0; i < digits.length; i++) {
        if (index == 0 && digits[i] == 0 && n > 1) {
            continue;
        }
        half[index] = (char) ('0' + digits[i]);
        half[half.length - 1 - index] = (char) ('0' + digits[4 - i]);
        generate(n, half, index + 1, result, digits);
    }
}
