import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        if (n <= 0) {
            return result;
        }
        backtrack(n, 0, new StringBuilder(), result);
        return result;
    }

    private static void backtrack(int n, int index, StringBuilder sb, List<String> result) {
        int len = sb.length();
        if (len == n) {
            result.add(sb.toString());
            return;
        }
        if (len < n - 1) {
            backtrack(n, index + 1, sb.append("0"), result);
            sb.setLength(len);
        }
        if (len < n || index > 0) {
            backtrack(n, index + 1, sb.append("1"), result);
            sb.setLength(len);
        }
        if (len < n || index > 0) {
            backtrack(n, index + 1, sb.append("8"), result);
            sb.setLength(len);
        }
        if (len <= n - 1 || index > 1) {
            backtrack(n, index + 1, sb.append("6").append("9"), result);
            sb.setLength(len);
            backtrack(n, index + 1, sb.append("9").append("6"), result);
            sb.setLength(len);
        }
    }

    public static void main(String[] args) {
        System.out.println(centerSymmetricNumbers(2)); // Output: [11, 69, 88, 96]
        System.out.println(centerSymmetricNumbers(1)); // Output: [0, 1, 8]
    }
}
