private static void helper(List<String> result, String current, int n, int max) {
    if (n == 0) {
        result.add(current);
        return;
    }
    if (n == 1) {
        result.add(current + "0");
        result.add(current + "1");
        result.add(current + "8");
        return;
    }
    for (char c : new char[]{'0', '1', '6', '8', '9'}) {
        if (current.length() == max - n && c == '0') {
            continue; // Avoid leading zeros
        }
        helper(result, current + c + findSymmetric(c) + current.substring(current.length() + 1), n - 2, max);
    }
}

private static char findSymmetric(char c) {
    switch (c) {
        case '1':
            return '1';
        case '6':
            return '9';
        case '8':
            return '8';
        case '9':
            return '6';
        default:
            throw new IllegalArgumentException("Invalid character for symmetric number");
    }
}
